import*as THREE from'../source/registration-vendor/three.module.js';
import{FaceLandmarker,FilesetResolver}from'../source/registration-vendor/vision_bundle.mjs';
import{FACE_CORRESPONDENCE}from'../source/registration-vendor/FaceCorrespondence.js';
const W=768,renderer=new THREE.WebGLRenderer({antialias:true,preserveDrawingBuffer:true});renderer.setSize(W,W);renderer.setPixelRatio(1);document.body.appendChild(renderer.domElement);renderer.outputColorSpace=THREE.SRGBColorSpace;
const scene=new THREE.Scene();scene.background=new THREE.Color('#343c43');scene.add(new THREE.HemisphereLight(0xffffff,0x545d68,1.0));const light=new THREE.DirectionalLight(0xfff0dc,2.0);light.position.set(-2,3,4);scene.add(light);const fill=new THREE.DirectionalLight(0xc7deff,.65);fill.position.set(3,2,1);scene.add(fill);let mesh,camera;
const read=async(n,T)=>new T(await(await fetch('../research/geometry/'+n)).arrayBuffer());
function display(name,v){const p=new Float32Array(v.length);for(let i=0;i<v.length;i+=3){if(name==='anny')p.set([v[i],v[i+2],-v[i+1]],i);else if(name==='mhr')p.set([v[i]*.01,v[i+1]*.01,v[i+2]*.01],i);else p.set(v.subarray(i,i+3),i);}return p;}
function native(name,p){return name==='anny'?[p.x,-p.z,p.y]:name==='mhr'?[p.x*100,p.y*100,p.z*100]:p.toArray();}
const fs=await FilesetResolver.forVisionTasks('../source/registration-vendor/wasm');const dc=document.createElement('canvas');dc.width=dc.height=1;const detector=await FaceLandmarker.createFromOptions(fs,{canvas:dc,baseOptions:{modelAssetPath:'../source/registration-vendor/face_landmarker.task',delegate:'CPU'},runningMode:'IMAGE',numFaces:1,minFaceDetectionConfidence:.5,minFacePresenceConfidence:.5,outputFacialTransformationMatrixes:true});
window.registrationProbe={async inspect(name){if(mesh){scene.remove(mesh);mesh.geometry.dispose();mesh.material.dispose();}const v=await read(name+'-vertices.f32',Float32Array),f=await read(name+'-faces.u32',Uint32Array),p=display(name,v),geometry=new THREE.BufferGeometry();geometry.setAttribute('position',new THREE.BufferAttribute(p,3));geometry.setIndex(new THREE.BufferAttribute(f,1));geometry.computeVertexNormals();const colors=new Float32Array(p.length),skin=new THREE.Color('#b9957b');for(let i=0;i<p.length;i+=3)colors.set(skin.toArray(),i);if(name==='gnm'){const ids=await read('gnm-materials.u32',Uint32Array),palette=['#b9957b','#e9e3d9','#b76c70','#c67679','#ece8dd','#647987','#141820'].map(x=>new THREE.Color(x));for(let i=0;i<ids.length;i++)colors.set(palette[ids[i]].toArray(),i*3);}if(name==='anny'){const ew=await read('anny-eye-weights.f32',Float32Array);for(let eye=0;eye<2;eye++){const ids=[];for(let i=0;i<v.length/3;i++)if(ew[i*2+eye]>.9)ids.push(i);const cx=ids.reduce((s,i)=>s+p[i*3],0)/ids.length,cy=ids.reduce((s,i)=>s+p[i*3+1],0)/ids.length;for(const i of ids){const d=Math.hypot(p[i*3]-cx,p[i*3+1]-cy);colors.set(new THREE.Color(d<.003?'#1a252a':d<.006?'#667e86':'#e4e2d8').toArray(),i*3);}}}geometry.setAttribute('color',new THREE.BufferAttribute(colors,3));mesh=new THREE.Mesh(geometry,new THREE.MeshStandardMaterial({vertexColors:true,roughness:.86,metalness:0,side:THREE.DoubleSide}));scene.add(mesh);const cutoff=name==='anny'?.52:name==='mhr'?1.4:.12;let lo=Infinity,hi=-Infinity;for(let i=1;i<p.length;i+=3)if(p[i]>cutoff){lo=Math.min(lo,p[i]);hi=Math.max(hi,p[i]);}const cy=(lo+hi)/2,extent=Math.max(.39,(hi-lo)*1.2);camera=new THREE.OrthographicCamera(-extent/2,extent/2,extent/2,-extent/2,.01,10);camera.position.set(0,cy,2);camera.lookAt(0,cy,0);camera.updateProjectionMatrix();scene.updateMatrixWorld(true);renderer.render(scene,camera);const result=detector.detect(renderer.domElement),landmarks=result.faceLandmarks[0]||[],ray=new THREE.Raycaster(),rows=[];for(let k=0;k<FACE_CORRESPONDENCE.landmarks.length;k++){const id=FACE_CORRESPONDENCE.landmarks[k],q=landmarks[id];if(!q)continue;ray.setFromCamera(new THREE.Vector2(q.x*2-1,1-q.y*2),camera);const hit=ray.intersectObject(mesh,false)[0];let record={landmark:id,gnmVertex:FACE_CORRESPONDENCE.vertices[k],screen:[q.x,q.y],detectorRelativeZ:q.z,hit:!!hit};if(hit){const ids=[hit.face.a,hit.face.b,hit.face.c],points=ids.map(i=>new THREE.Vector3().fromArray(p,i*3)),bary=THREE.Triangle.getBarycoord(hit.point,...points,new THREE.Vector3());record={...record,face:hit.faceIndex,vertices:ids,barycentric:bary.toArray(),nativePoint:native(name,hit.point),displayPoint:hit.point.toArray()};}if(name==='gnm'){const x=new THREE.Vector3().fromArray(p,record.gnmVertex*3).project(camera);record.actualNativeGNMPoint=Array.from(v.subarray(record.gnmVertex*3,record.gnmVertex*3+3));record.actualGNMScreen=[(x.x+1)/2,(1-x.y)/2];record.detectorVsNativePixels=Math.hypot(q.x-record.actualGNMScreen[0],q.y-record.actualGNMScreen[1])*W;}rows.push(record);}document.querySelector('#status').textContent=name+' · '+landmarks.length+' detected points · '+rows.filter(x=>x.hit).length+' geometry hits';renderer.render(scene,camera);return{name,vertices:v.length/3,faces:f.length/3,detected:landmarks.length,matched:rows.length,camera:{type:'orthographic',position:camera.position.toArray(),target:[0,cy,0],extent,resolution:W},landmarks:rows,materialNote:'Diagnostic neutral geometry with shared lighting. GNM component colors; Anny native eye components receive diagnostic iris contrast. MHR stays untextured. This is a landmark proposal, not a semantic accuracy pass.',modelTaskSHA256:'64184e229b263107bc2b804c6625db1341ff2bb731874b0bcc2fe6544e0bc9ff'};},dispose(){detector.close();renderer.dispose();}};window.probeReady=true;
